const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define South Los Angeles geometry
  const southLA = ee.Geometry.Polygon([
    [-118.35, 33.95],
    [-118.35, 34.00], 
    [-118.20, 34.00],
    [-118.20, 33.95],
    [-118.35, 33.95]
  ]);

  // Function to get NO2 data for a given year
  async function getNO2Data(year) {
    const startDate = year + '-10-01';
    const endDate = year + '-10-23';

    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(southLA)
      .select('tropospheric_NO2_column_number_density');

    const count = collection.size().getInfo();
    console.log(`${year} Images: ${count}`);

    if (count === 0) return {mean: null, pixelCount: 0, valid: false};

    const meanImage = collection.mean();

    // Check pixel count
    const pixelStats = meanImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: southLA,
      scale: 1000,
      maxPixels: 1e9
    });
    const pixelCount = pixelStats.get('tropospheric_NO2_column_number_density').getInfo();

    if (pixelCount === 0) return {mean: null, pixelCount: 0, valid: false};

    // Calculate mean NO2 concentration
    const meanStats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: southLA,
      scale: 1000,
      maxPixels: 1e9
    });
    const meanValue = meanStats.get('tropospheric_NO2_column_number_density').getInfo();

    return {
      mean: meanValue,
      pixelCount: pixelCount,
      valid: meanValue !== null && !isNaN(meanValue)
    };
  }

  // Get data for all three years
  const data2018 = await getNO2Data('2018');
  const data2019 = await getNO2Data('2019'); 
  const data2021 = await getNO2Data('2021');

  // Check for data issues
  if (!data2018.valid || !data2019.valid || !data2021.valid) {
    if (data2018.pixelCount === 0 || data2019.pixelCount === 0 || data2021.pixelCount === 0) {
      console.log("No valid pixels in one or more years");
      console.log("<answer>C2</answer>");
      return;
    }
    console.log("Calculation failed for one or more years");
    console.log("<answer>C3</answer>");
    return;
  }

  // Print results
  console.log(`2018 NO2: ${data2018.mean.toFixed(6)} mol/m²`);
  console.log(`2019 NO2: ${data2019.mean.toFixed(6)} mol/m²`);
  console.log(`2021 NO2: ${data2021.mean.toFixed(6)} mol/m²`);
  console.log(`2021 < 2019: ${data2021.mean < data2019.mean}`);
  console.log(`2021 < 2018: ${data2021.mean < data2018.mean}`);

  // Determine answer
  if (data2021.mean < data2019.mean && data2021.mean < data2018.mean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
